package learn

import (
	"bytes"
	"cmp"
	"sort"
	"strconv"
	"strings"

	"go.keploy.io/server/v3/pkg/models"
)

// Compact learned-variable why lines and their per-file header block.
//
// Each learned variable in mocks.yaml carries one compact why line starting
// with "[<kind>] " and only that variable's own evidence (test, place, values,
// source/rule, and undo target). The fixed explanation, rule text, and undo
// template for each kind are written once per mocks.yaml file in a leading
// YAML comment block (# keploy-learned-kinds: v1 .. # keploy-learned-kinds-end)
// regenerated by every writer of mocks.yaml from the kinds its mocks name.
// YAML readers skip comments and packs never carry the header, while a human
// or LLM reading mocks.yaml alone can resolve every variable's full
// explanation and exact undo from the header and that line.

const (
	WhyKindValue       = "value"
	WhyKindFresh       = "fresh"
	WhyKindClock       = "clock"
	WhyKindCarried     = "carried"
	WhyKindCarriedBind = "carried-bind"
	WhyKindAnswered    = "answered"

	WhyHeaderStart = "# keploy-learned-kinds: v1"
	WhyHeaderEnd   = "# keploy-learned-kinds-end"

	defaultValueRuleSuffix = ", the earliest place before the call that shows it in both runs"
	defaultFreshRule       = "no place before the call shows it; bound at its first call"
)

// WhyKindDoc is the per-kind explanation and templates stored in a mocks.yaml
// header block.
type WhyKindDoc struct {
	What string
	Rule string
	Undo string
}

// whyKindDocs is the canonical definition of every compact learned kind,
// written once per mocks.yaml for the kinds that file's mocks use.
var whyKindDocs = map[string]WhyKindDoc{
	WhyKindValue: {
		What: "value bound at its source, checked at every later use",
		Rule: "bound to <from>, the earliest place before the call that shows it in both runs (see `rule`, `window`, `places`, `whole` when present)",
		Undo: `in keploy.yml, test.globalNoise.global.<section>: {"<key>": []} (the whole field: keploy.yml names no word; for url, a regex of the changing part of <key>), or the same under test.globalNoise.test-sets.<the test set>: noise for every mock there; or re-record (using undo="<section>:<key>", or re-record alone when undo="re-record")`,
	},
	WhyKindFresh: {
		What: "value made anew each run, bound at its first call and checked at every later use",
		Rule: "no place before the call shows it; bound at its first call (see `rule`, `window`, `places`, `whole` when present)",
		Undo: `in keploy.yml, test.globalNoise.global.<section>: {"<key>": []} (the whole field: keploy.yml names no word; for url, a regex of the changing part of <key>), or the same under test.globalNoise.test-sets.<the test set>: noise for every mock there; or re-record (using undo="<section>:<key>", or re-record alone when undo="re-record")`,
	},
	WhyKindClock: {
		What: "clock read, checked in its call's span",
		Rule: "as named by `rule` (see `window`, `places` when present)",
		Undo: `in keploy.yml, test.globalNoise.global.<section>: {"<key>": []} (the whole field: keploy.yml names no word; for url, a regex of the changing part of <key>), or the same under test.globalNoise.test-sets.<the test set>: noise for every mock there; or re-record (using undo="<section>:<key>", or re-record alone when undo="re-record")`,
	},
	WhyKindCarried: {
		What: "value carried from an earlier call of the same test that makes it anew each run (bound whole there); no call of record's full round paired with this recording, which holds the value whole after that call, so replay checks each use place against that run's value",
		Rule: "carried from <from> of <test>",
		Undo: "delete this variable from this mock",
	},
	WhyKindCarriedBind: {
		What: "value bound for the run beside a test's own variable so later recordings of that test that hold it whole can carry and check it",
		Rule: "bound at <at> for <test>",
		Undo: "delete this variable from this mock",
	},
	WhyKindAnswered: {
		What: "answer field populated from a bound variable at replay",
		Rule: "answered at <at> from <from> (<detail>)",
		Undo: "re-record",
	},
}

// knownWhyKind reports whether k is a registered compact why kind.
func knownWhyKind(k string) bool {
	_, ok := whyKindDocs[k]
	return ok
}

// CompactLine returns d's compact why line for persistence in mocks.yaml,
// falling back to d.Line when d was constructed without a compact line.
func CompactLine(d Decision) string {
	if d.Compact != "" {
		return d.Compact
	}
	return d.Line
}

// compactUndoTarget is the compact undo token for field: "<bucket>:<key>"
// when keploy.yml noise names the field, else "re-record".
func compactUndoTarget(field string) string {
	bucket, key, ok := noiseAt(field)
	if !ok {
		return "re-record"
	}
	if bucket == "url" {
		return "url:" + field
	}
	if uq, err := strconv.Unquote(key); err == nil {
		key = uq
	}
	return bucket + ":" + key
}

// appendKV appends ` key="val"` to b when val is non-empty.
func appendKV(b *strings.Builder, key, val string) {
	if val == "" {
		return
	}
	b.WriteByte(' ')
	b.WriteString(key)
	b.WriteByte('=')
	b.WriteString(strconv.Quote(val))
}

// compactLearnedLine formats l as one compact "[<kind>] k=v ..." line carrying
// only l's own evidence and undo target, with the same secret masking as
// learnedLine.
func compactLearnedLine(l learnedWord) string {
	var kind string
	switch l.Outcome {
	case OutcomeValue:
		kind = WhyKindValue
	case OutcomeFresh:
		kind = WhyKindFresh
	case OutcomeClock:
		kind = WhyKindClock
	default:
		return learnedLine(l)
	}
	rec, full, rule := l.Recorded, l.Full, l.Rule
	if secretAt(l.Field, l.Places) {
		rec, full, rule = masked, masked, hidden(rule)
	}
	at := l.Field
	if l.Word >= 0 {
		at += "#" + strconv.Itoa(l.Word)
	}
	var b strings.Builder
	b.WriteByte('[')
	b.WriteString(kind)
	b.WriteByte(']')
	appendKV(&b, "test", l.Test)
	appendKV(&b, "at", at)
	appendKV(&b, "rec", rec)
	appendKV(&b, "full", full)

	places := l.Places
	if len(places) > maxLinePlaces {
		places = places[:maxLinePlaces]
	}
	switch kind {
	case WhyKindValue:
		if rest, ok := strings.CutPrefix(rule, "bound to "); ok {
			if from, ok := strings.CutSuffix(rest, defaultValueRuleSuffix); ok && from != "" {
				appendKV(&b, "from", from)
				if len(places) == 1 && places[0] == from {
					places = nil
				}
				rule = ""
			}
		}
		appendKV(&b, "rule", rule)
	case WhyKindFresh:
		if rule != defaultFreshRule {
			appendKV(&b, "rule", rule)
		}
	case WhyKindClock:
		appendKV(&b, "rule", rule)
	}
	appendKV(&b, "window", l.From)
	if len(places) > 0 {
		appendKV(&b, "places", strings.Join(places, ", "))
	}
	appendKV(&b, "undo", compactUndoTarget(cmp.Or(l.Noise, l.Field)))
	return b.String()
}

// CompactCarriedWhy formats one compact why line for a variable carried from
// an earlier recording of test at from ("<mock> <bind>").
func CompactCarriedWhy(test, from string) string {
	var b strings.Builder
	b.WriteString("[" + WhyKindCarried + "]")
	appendKV(&b, "test", test)
	appendKV(&b, "from", from)
	return b.String()
}

// CompactCarriedBindWhy formats one compact why line for a run-level bind
// written beside test's own variable at at ("<mock> <bind>") for carried uses.
func CompactCarriedBindWhy(test, at string) string {
	var b strings.Builder
	b.WriteString("[" + WhyKindCarriedBind + "]")
	appendKV(&b, "test", test)
	appendKV(&b, "at", at)
	return b.String()
}

// CompactAnsweredWhy formats one compact why line for an answer place filled
// from a variable bound at from.
func CompactAnsweredWhy(at, recorded, full, from, detail string) string {
	rec, live := recorded, full
	if secretAt(at, []string{from}) {
		rec, live = masked, masked
	}
	var b strings.Builder
	b.WriteString("[" + WhyKindAnswered + "]")
	appendKV(&b, "at", at)
	appendKV(&b, "rec", rec)
	appendKV(&b, "full", live)
	appendKV(&b, "from", from)
	appendKV(&b, "detail", detail)
	return b.String()
}

// AppendWholeNote attaches a whole-field bind note to why: as a `whole="..."`
// field on a compact line, or appended inline on a plain line.
func AppendWholeNote(why, note string) string {
	if note == "" {
		return why
	}
	if _, ok := WhyKindOf(why); ok {
		var b strings.Builder
		b.WriteString(why)
		appendKV(&b, "whole", note)
		return b.String()
	}
	return why + ". " + note
}

// WhyKindOf returns the compact kind named at the start of whyLine
// ("[<kind>] ..."), or ("", false) when whyLine does not start with a known
// kind tag.
func WhyKindOf(whyLine string) (string, bool) {
	if !strings.HasPrefix(whyLine, "[") {
		return "", false
	}
	end := strings.IndexByte(whyLine, ']')
	if end <= 1 {
		return "", false
	}
	k := whyLine[1:end]
	if !knownWhyKind(k) {
		return "", false
	}
	if end+1 < len(whyLine) && whyLine[end+1] != ' ' {
		return "", false
	}
	return k, true
}

// WhyKindsInVars returns the sorted unique compact why kinds referenced by
// vars' Why lines (and their Clock entries' Why lines).
func WhyKindsInVars(vars models.MockVariables) []string {
	if len(vars) == 0 {
		return nil
	}
	seen := map[string]bool{}
	scan := func(s string) {
		for _, line := range strings.Split(s, "\n") {
			if k, ok := WhyKindOf(strings.TrimSpace(line)); ok {
				seen[k] = true
			}
		}
	}
	for _, v := range vars {
		if v.Why != "" {
			scan(v.Why)
		}
		for _, c := range v.ByForm {
			if c.Why != "" {
				scan(c.Why)
			}
		}
	}
	return sortedKinds(seen)
}

// WhyKindsInYAML scans a YAML mock document's top-level variables: block for
// compact "[<kind>] " why tags without decoding the whole document.
func WhyKindsInYAML(doc []byte) []string {
	if !bytes.Contains(doc, []byte("variables:")) {
		return nil
	}
	seen := map[string]bool{}
	inVars := false
	for len(doc) > 0 {
		line := doc
		if i := bytes.IndexByte(doc, '\n'); i >= 0 {
			line = doc[:i+1]
			doc = doc[i+1:]
		} else {
			doc = nil
		}
		trimmed := bytes.TrimRight(line, "\r\n")
		if len(trimmed) > 0 && trimmed[0] != ' ' && trimmed[0] != '\t' && trimmed[0] != '#' {
			inVars = bytes.HasPrefix(trimmed, []byte("variables:")) &&
				(len(trimmed) == len("variables:") || trimmed[len("variables:")] == ' ')
			continue
		}
		if !inVars {
			continue
		}
		s := strings.TrimSpace(string(trimmed))
		if rest, ok := strings.CutPrefix(s, "why:"); ok {
			s = strings.TrimSpace(rest)
			if s == "|-" || s == "|" || s == ">-" || s == ">" || s == "" {
				continue
			}
		}
		s = trimYAMLQuote(s)
		if k, ok := WhyKindOf(s); ok {
			seen[k] = true
		}
	}
	return sortedKinds(seen)
}

func trimYAMLQuote(s string) string {
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		if uq, err := strconv.Unquote(s); err == nil {
			return uq
		}
	}
	return s
}

func sortedKinds(seen map[string]bool) []string {
	if len(seen) == 0 {
		return nil
	}
	out := make([]string, 0, len(seen))
	for k := range seen {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// FormatWhyHeader formats the YAML comment header block documenting every
// known kind in kinds (deduplicated and sorted). Returns "" when kinds names
// no known kind.
func FormatWhyHeader(kinds []string) string {
	seen := map[string]bool{}
	for _, k := range kinds {
		if knownWhyKind(k) {
			seen[k] = true
		}
	}
	ordered := sortedKinds(seen)
	if len(ordered) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString(WhyHeaderStart + "\n")
	for _, k := range ordered {
		d := whyKindDocs[k]
		b.WriteString("#   [" + k + "]\n")
		b.WriteString("#     what: " + d.What + "\n")
		b.WriteString("#     rule: " + d.Rule + "\n")
		b.WriteString("#     undo: " + d.Undo + "\n")
	}
	b.WriteString(WhyHeaderEnd + "\n")
	return b.String()
}

// StripWhyHeader removes any leading # keploy-learned-kinds: v1 .. end block
// from raw (which may begin after a version comment or other leading comments),
// leaving all other comments and document bytes intact.
func StripWhyHeader(raw []byte) []byte {
	startMark := []byte(WhyHeaderStart)
	if !bytes.Contains(raw, startMark) {
		return raw
	}
	var out bytes.Buffer
	inHeader := false
	seenDoc := false
	rest := raw
	for len(rest) > 0 {
		line := rest
		if i := bytes.IndexByte(rest, '\n'); i >= 0 {
			line = rest[:i+1]
			rest = rest[i+1:]
		} else {
			rest = nil
		}
		trimmed := strings.TrimRight(string(line), "\r\n")
		if !seenDoc {
			if trimmed == WhyHeaderStart {
				inHeader = true
				continue
			}
			if inHeader {
				if trimmed == WhyHeaderEnd {
					inHeader = false
				}
				continue
			}
			if trimmed != "" && !strings.HasPrefix(trimmed, "#") {
				seenDoc = true
			}
		}
		out.Write(line)
	}
	return out.Bytes()
}

// ParseWhyHeader reads the # keploy-learned-kinds: v1 comment block from raw
// (a mocks.yaml file or its leading comments) and returns the per-kind
// explanation and templates keyed by kind name.
func ParseWhyHeader(raw []byte) map[string]WhyKindDoc {
	out := map[string]WhyKindDoc{}
	inHeader := false
	cur := ""
	rest := raw
	for len(rest) > 0 {
		line := rest
		if i := bytes.IndexByte(rest, '\n'); i >= 0 {
			line = rest[:i+1]
			rest = rest[i+1:]
		} else {
			rest = nil
		}
		s := strings.TrimRight(string(line), "\r\n")
		if !inHeader {
			if s == WhyHeaderStart {
				inHeader = true
				continue
			}
			if s != "" && !strings.HasPrefix(s, "#") {
				break
			}
			continue
		}
		if s == WhyHeaderEnd {
			break
		}
		body, ok := strings.CutPrefix(s, "#")
		if !ok {
			break
		}
		t := strings.TrimSpace(body)
		if strings.HasPrefix(t, "[") && strings.HasSuffix(t, "]") && len(t) > 2 {
			cur = t[1 : len(t)-1]
			if _, exists := out[cur]; !exists {
				out[cur] = WhyKindDoc{}
			}
			continue
		}
		if cur == "" {
			continue
		}
		d := out[cur]
		switch {
		case strings.HasPrefix(t, "what: "):
			d.What = strings.TrimPrefix(t, "what: ")
		case strings.HasPrefix(t, "rule: "):
			d.Rule = strings.TrimPrefix(t, "rule: ")
		case strings.HasPrefix(t, "undo: "):
			d.Undo = strings.TrimPrefix(t, "undo: ")
		}
		out[cur] = d
	}
	return out
}

// ResolvedWhy is the full explanation and exact undo resolved for one compact
// why line using only the mocks.yaml header block and that line's own fields.
type ResolvedWhy struct {
	Kind   string
	Fields map[string]string
	What   string
	Rule   string
	Undo   string
}

// ResolveWhy resolves whyLine using ONLY header (parsed from mocks.yaml via
// ParseWhyHeader), returning the kind's full explanation, filled rule, and
// exact undo for that line's path. Returns ok=false when whyLine is not a
// compact line or header does not define its kind.
func ResolveWhy(header map[string]WhyKindDoc, whyLine string) (ResolvedWhy, bool) {
	if !strings.HasPrefix(whyLine, "[") {
		return ResolvedWhy{}, false
	}
	end := strings.IndexByte(whyLine, ']')
	if end <= 1 {
		return ResolvedWhy{}, false
	}
	kind := whyLine[1:end]
	doc, ok := header[kind]
	if !ok {
		return ResolvedWhy{}, false
	}
	fields, ok := parseCompactKV(strings.TrimSpace(whyLine[end+1:]))
	if !ok {
		return ResolvedWhy{}, false
	}
	rule := doc.Rule
	if r := fields["rule"]; r != "" {
		rule = r
	} else {
		rule = strings.NewReplacer(
			"<from>", fields["from"],
			"<test>", fields["test"],
			"<at>", fields["at"],
			"<detail>", fields["detail"],
		).Replace(rule)
	}
	if w := fields["window"]; w != "" {
		rule += ", learned from round F's call in " + w + ", for learning only"
	}
	if ps := fields["places"]; ps != "" {
		rule += ". Places: " + ps
	}
	if wh := fields["whole"]; wh != "" {
		rule += ". " + wh
	}
	undo := resolveUndoTemplate(doc.Undo, fields["undo"])
	return ResolvedWhy{
		Kind:   kind,
		Fields: fields,
		What:   doc.What,
		Rule:   rule,
		Undo:   undo,
	}, true
}

func resolveUndoTemplate(tmpl, target string) string {
	if target == "" {
		return tmpl
	}
	if target == "re-record" {
		return "re-record"
	}
	sec, key, ok := strings.Cut(target, ":")
	if !ok || sec == "" || key == "" {
		return tmpl
	}
	base, _, _ := strings.Cut(tmpl, " (using undo=")
	return strings.NewReplacer("<section>", sec, "<key>", key).Replace(base)
}

func parseCompactKV(s string) (map[string]string, bool) {
	out := map[string]string{}
	for len(s) > 0 {
		s = strings.TrimLeft(s, " ")
		if s == "" {
			break
		}
		eq := strings.IndexByte(s, '=')
		if eq <= 0 {
			return nil, false
		}
		k := s[:eq]
		rest := s[eq+1:]
		if !strings.HasPrefix(rest, `"`) {
			return nil, false
		}
		q, err := strconv.QuotedPrefix(rest)
		if err != nil {
			return nil, false
		}
		v, err := strconv.Unquote(q)
		if err != nil {
			return nil, false
		}
		out[k] = v
		s = rest[len(q):]
		if len(s) > 0 && s[0] != ' ' {
			return nil, false
		}
	}
	return out, true
}

// MergeWhyKinds adds every kind in add into dst (creating dst if nil).
func MergeWhyKinds(dst map[string]bool, add []string) map[string]bool {
	for _, k := range add {
		if knownWhyKind(k) {
			if dst == nil {
				dst = map[string]bool{}
			}
			dst[k] = true
		}
	}
	return dst
}

// SortedWhyKinds returns the sorted slice of keys in m.
func SortedWhyKinds(m map[string]bool) []string {
	return sortedKinds(m)
}
